python3 -I -B -c "import json,hashlib,os
def h(p):
    b=open(p,'rb').read();return hashlib.sha256(b).hexdigest(),len(b)
cp=json.load(open('benchmark/writing/current-pins.json'))
bad=0
for sec in('current','frozen'):
    for p,v in cp[sec].items():
        if not os.path.exists(p):print('MISSING',p);bad+=1;continue
        s,z=h(p)
        if s!=v['sha256'] or z!=v['size']:print('MISMATCH',sec,p);bad+=1
print('current-pins',len(cp['current']),len(cp['frozen']),'bad',bad)
ip=json.load(open('benchmark/writing/input-pins.json'))
print(list(ip.keys()))
m=ip.get('protected_inputs_sha256',{});bad=0
for p,s in m.items():
    if not os.path.exists(p):print('MISSING',p);bad+=1;continue
    if h(p)[0]!=s:print('MISMATCH',p);bad+=1
print('input-pins',len(m),'bad',bad)
pj=json.load(open('benchmark/preparation.json'))
out=[]
def walk(o):
    if isinstance(o,dict):
        if isinstance(o.get('path'),str) and 'sha256' in o:out.append((o['path'],o['sha256']))
        for v in o.values():walk(v)
    elif isinstance(o,list):
        for v in o:walk(v)
walk(pj)
bad=0
for p,s in out:
    if not os.path.exists(p):print('MISSING',p);bad+=1;continue
    if h(p)[0]!=s:print('PREP MISMATCH',p);bad+=1
print('preparation pins',len(out),'bad',bad)
"

